package game

import "core:math/linalg"
import "engine:engine"
import "engine:input"

OPEN_REACH :: 1.4 // metres from the goblin to a chest's centre

// Finds the nearest closed chest in reach; E opens it, adds its gold and makes the goblin wave.
update_chests :: proc() {
	here := engine.world_position(game.player)
	game.near = 0
	best := f32(OPEN_REACH)
	ents, chests := engine.view(Chest)
	for c, i in chests {
		if c.open do continue
		d := linalg.length((engine.world_position(ents[i]) - here).xz)
		if d < best do best, game.near = d, ents[i]
	}
	if game.near != 0 && input.action_pressed("interact") do open_chest(game.near)
}

open_chest :: proc(e: Entity) {
	c := engine.get(e, Chest)
	if c == nil || c.open do return
	c.open = true
	game.gold += c.gold
	engine.play_animation(e, "open", once = true)
	engine.play_sound(JINGLE_TREASURE, volume = 0.9, bus = .Music)
	// Face the chest while celebrating.
	if t := engine.get(game.player, engine.Transform); t != nil {
		to := engine.world_position(e) - engine.world_position(game.player)
		to.y = 0
		if linalg.length(to) > 0.01 do t.rotation = engine.look_rotation(to)
	}
	celebrate()
}

chests_left :: proc() -> (left, total: int) {
	_, chests := engine.view(Chest)
	for c in chests {
		total += 1
		if !c.open do left += 1
	}
	return
}
package game

import "core:fmt"
import "engine:ui"

draw_ui :: proc() {
	left, total := chests_left()

	r := ui.anchor(.Top_Left, 230, 76, {16, 16})
	ui.panel(r)
	col := ui.column(ui.inset(r, 12), 26, 2)
	ui.label(ui.next(&col), fmt.tprintf("Gold: %d", game.gold), size = 26)
	ui.label(ui.next(&col), fmt.tprintf("Chests: %d / %d opened", total - left, total), color = ui.theme().text_dim)

	if game.near != 0 {
		p := ui.anchor(.Bottom, 260, 44, {0, 60})
		ui.panel(p)
		ui.label(p, "E  Open the chest", .Center)
	}
	if total > 0 && left == 0 {
		b := ui.anchor(.Top, 520, 70, {0, 40})
		ui.panel(b)
		ui.label(b, "The clearing is cleared!", .Center, 34)
	}
	hint := ui.anchor(.Bottom_Right, 330, 30, {16, 12})
	ui.label(hint, "WASD walk   |   right-drag look   |   wheel zoom", .Right, 16, ui.theme().text_dim)
}
// Goblin Gold: walk a mossy clearing as a goblin and open every treasure chest. See docs/design/Overview.md.
// Content (the clearing, the goblin, chests, barrels, boulders) is in assets/scenes and assets/prefabs.
package game

import "core:strconv"
import "engine:engine"
import "engine:input"

Vec3 :: engine.Vec3
Entity :: engine.Entity

// Marks the goblin the player controls.
Player :: struct {
	celebrating: bool, // playing the wave after opening a chest
}

// A treasure chest. `open` turns true once the goblin opens it (the lid plays its "open" clip).
Chest :: struct {
	gold: int,
	open: bool,
}

game: struct {
	player:    Entity,
	gold:      int,
	cam_yaw:   f32, // degrees; 0 looks along +Z
	cam_pitch: f32,
	cam_dist:  f32,
	near:      Entity, // the closed chest the goblin can open right now, if any
}

main :: proc() {
	engine.run({setup = setup, init = init, update = update, draw_ui = draw_ui}, {title = "Goblin Gold", scene = "scenes/clearing.json"})
}

setup :: proc() {
	engine.register_component(Player)
	engine.register_component(Chest)
	input.bind("move_x", input.key(.A, -1), input.key(.D), input.key(.LEFT, -1), input.key(.RIGHT), input.pad_stick(.LEFT_X))
	input.bind("move_y", input.key(.W), input.key(.S, -1), input.key(.UP), input.key(.DOWN, -1), input.pad_stick(.LEFT_Y, -1))
	input.bind("look_x", input.pad_stick(.RIGHT_X))
	input.bind("interact", input.key(.E), input.pad_button(.RIGHT_FACE_DOWN))

	// For tests and agents: move the goblin instantly.
	engine.register_command("teleport", "teleport X Z: put the goblin at (X, 0, Z)", proc(args: []string) -> string {
		if game.player == 0 || len(args) != 2 do return "usage: teleport X Z"
		x, _ := strconv.parse_f32(args[0])
		z, _ := strconv.parse_f32(args[1])
		engine.get(game.player, engine.Transform).position = {x, 0.05, z}
		engine.skip_interpolation(game.player)
		return "ok"
	})
}

MUSIC_THEME :: "music/goblin-gold/goblin-gold.ogg" // the Music section's "Goblin Gold" (loops)
JINGLE_TREASURE :: "music/treasure-found/treasure-found.ogg" // "Treasure Found" (plays once)

init :: proc() {
	engine.play_music(MUSIC_THEME, volume = 0.6)
	game.player = engine.find("Goblin")
	game.cam_pitch = 25
	game.cam_dist = 4.5
}

update :: proc(dt: f32) {
	if game.player == 0 || !engine.alive(game.player) do return
	control_player(dt)
	update_chests()
	update_camera(dt)
}

// The goblin's model is the root's child (the root is the walking capsule).
goblin_model :: proc() -> Entity {
	for child in engine.children(game.player) do if engine.get(child, engine.Animator) != nil do return child
	return 0
}
package game

import "core:math"
import "core:math/linalg"
import "engine:engine"
import "engine:input"
import "engine:ui"

WALK_SPEED :: 2.2 // m/s; matches the walk clip's stride at a 1.1 m goblin
TURN_SHARPNESS :: 10

// WASD moves relative to the camera; the goblin turns to face where it walks and plays idle, walk or wave.
control_player :: proc(dt: f32) {
	cc := engine.get(game.player, engine.Character_Controller)
	t := engine.get(game.player, engine.Transform)
	p := engine.get(game.player, Player)
	if cc == nil || t == nil || p == nil do return

	move := input.action_vector("move_x", "move_y") if !ui.wants_keyboard() else {}
	yaw := math.to_radians(game.cam_yaw)
	forward := Vec3{math.sin(yaw), 0, math.cos(yaw)}
	right := Vec3{-math.cos(yaw), 0, math.sin(yaw)}
	wish := right * move.x + forward * move.y
	moving := linalg.length(wish) > 0.1

	cc.velocity.xz = linalg.lerp(cc.velocity.xz, wish.xz * WALK_SPEED, engine.damp(12, dt))
	if moving do t.rotation = linalg.quaternion_slerp(t.rotation, engine.look_rotation(wish), engine.damp(TURN_SHARPNESS, dt))

	model := goblin_model()
	an := engine.get(model, engine.Animator)
	if an == nil do return
	if p.celebrating && (moving || an.finished) do p.celebrating = false
	if p.celebrating do return
	engine.play_animation(model, "walk" if moving else "idle")
}

// The goblin waves once (walking cuts it short).
celebrate :: proc() {
	if p := engine.get(game.player, Player); p != nil do p.celebrating = true
	engine.play_animation(goblin_model(), "wave", once = true, restart = true)
}

// A third-person camera behind the goblin: drag with the right mouse button to turn it, wheel to zoom.
update_camera :: proc(dt: f32) {
	cam := engine.find("Camera")
	if cam == 0 do return
	if input.mouse_down(.RIGHT) && !ui.wants_mouse() {
		d := input.mouse_delta()
		game.cam_yaw -= d.x * 0.25
		game.cam_pitch = clamp(game.cam_pitch + d.y * 0.2, 5, 70)
	}
	game.cam_yaw -= input.action_value("look_x") * 120 * dt
	game.cam_dist = clamp(game.cam_dist - input.mouse_wheel() * 0.5, 2, 10)

	target := engine.world_position(game.player) + {0, 0.8, 0}
	yaw, pitch := math.to_radians(game.cam_yaw), math.to_radians(game.cam_pitch)
	dir := Vec3{math.cos(pitch) * math.sin(yaw), -math.sin(pitch), math.cos(pitch) * math.cos(yaw)}
	dist := game.cam_dist
	if hit, ok := engine.raycast(target, -dir, dist, ignore = game.player); ok do dist = max(hit.distance - 0.3, 0.5)
	t := engine.get(cam, engine.Transform)
	t.position = linalg.lerp(t.position, target - dir * dist, engine.damp(20, dt))
	engine.look_at(cam, target)
}
