@(private)
clip_duration :: proc(anim: ^rl.ModelAnimation) -> f32 {
	return f32(max(anim.keyframeCount - 1, 1)) / ANIMATION_FPS
}

// Seconds in the named clip of the entity's model, or 0 when unknown.
animation_duration :: proc(e: Entity, clip: string) -> f32 {
	mr := get(e, Mesh_Renderer)
	if mr == nil do return 0
	a := resolve_mesh(mr)
	if a == nil do return 0
	anim, ok := find_clip(a, clip)
	return clip_duration(anim) if ok else 0
}

// Switches clip with a crossfade. Restarts the clip when `restart` is set or the clip changes.
play_animation :: proc(e: Entity, clip: string, once := false, restart := false) {
	an := ensure(e, Animator)
	if an.clip != clip || restart {
		an.clip = strings.clone(clip, ecs.data_allocator(&g.world))
		if restart && an._current == clip {
			an._current = ""
			an.time = 0
		}
	}
	an.once = once
	an.paused = false
}

// `settle` (while paused): pose every animator without advancing time, finishing any blend. A `once` clip
// that starts while paused shows its end pose, the state it describes (a chest's "close").
@(private)
animation_update :: proc(dt: f32, settle := false) {
	ents, ans := ecs.view(&g.world, Animator)
	for &an, i in ans {
		started := false
		if an.clip != an._current {
			started = true
			alloc := ecs.data_allocator(&g.world)
			had_previous := an._current != ""
			an._prev = an._current
			an._prev_time = an.time
			an._current = strings.clone(an.clip, alloc)
			if had_previous do an.time = 0 // the first clip starts at the given time (a scene can open a chest's "close" at its end)
			an.finished = false
			an._blend = 0 if had_previous else 1
		}
		if settle {
			an._blend = 1
			if started && an.once {
				if d := animation_duration(ents[i], an._current); d > 0 {
					an.time = d
					an.finished = true
				}
			}
			continue
		}
		if an.paused do continue
		speed := an.speed if an.speed != 0 else 1
		an.time += dt * speed
		an._prev_time += dt * speed
		fade := an.fade if an.fade > 0 else 0.2
		an._blend = min(an._blend + dt / fade, 1)
		if an.once {
			if d := animation_duration(ents[i], an._current); d > 0 && an.time >= d {
				an.time = d
				an.finished = true
			}
		}
	}
}

